parameters.jsCode:
const d = $input.first().json;

const wmo = {
  0: 'שמיים בהירים', 1: 'בהיר ברובו', 2: 'מעונן חלקית', 3: 'מעונן',
  45: 'ערפל', 48: 'ערפל', 51: 'טפטוף קל', 53: 'טפטוף', 55: 'טפטוף כבד',
  61: 'גשם קל', 63: 'גשם', 65: 'גשם כבד', 80: 'ממטרים', 81: 'ממטרים',
  82: 'ממטרים חזקים', 95: 'סופת רעמים', 96: 'סופת רעמים', 99: 'סופת רעמים'
};
const dayNames = ['ראשון','שני','שלישי','רביעי','חמישי','שישי','שבת'];

const now = d.current.temperature_2m;
const feels = d.current.apparent_temperature;
const desc = wmo[d.current.weather_code] ?? 'לא ידוע';

const days = d.daily.time.map((t, i) => ({
  label: 'יום ' + dayNames[new Date(t).getDay()],
  max: d.daily.temperature_2m_max[i],
  min: d.daily.temperature_2m_min[i],
  rain: d.daily.precipitation_probability_max[i],
  desc: wmo[d.daily.weather_code[i]] ?? ''
}));

const today = days[0];

// נתונים לגרף (QuickChart)
const chartConfig = {
  type: 'line',
  data: {
    labels: days.map(x => x.label),
    datasets: [
      { label: 'מקסימום', data: days.map(x => x.max), borderColor: '#e8590c', fill: false },
      { label: 'מינימום', data: days.map(x => x.min), borderColor: '#1c7ed6', fill: false }
    ]
  },
  options: { title: { display: true, text: 'תחזית 5 ימים בירושלים (°C)' } }
};
const chartUrl = 'https://quickchart.io/chart?w=600&h=300&bkg=white&c=' +
  encodeURIComponent(JSON.stringify(chartConfig));

// טקסט עבור ה-AI
const aiInput =
`עכשיו: ${now}° (מרגיש כמו ${feels}°), מצב: ${desc}
היום: מקסימום ${today.max}°, מינימום ${today.min}°, סיכוי לגשם ${today.rain}%
בימים הקרובים:
` + days.slice(1).map(x => `${x.label}: ${x.min}°-${x.max}°, גשם ${x.rain}%`).join('\n');

return [{ json: { now, feels, desc, today, days, chartUrl, aiInput } }];

